package compiler.runtime;

import compiler.parser.Ast;
import compiler.parser.ParseResult;
import compiler.parser.Parser;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * InsertGenerated：只有签名与生成子句、没有等式的基 trait。
 * 用于验证「声明 → generated by 定义」这条路的结构检查。
 */
class InsertGeneratedSpecTest {

    private static final String SAMPLE = """
            InsertGenerated(E, C): trait
              introduces
                empty: → C
                insert: E, C → C
              asserts
                C generated by empty, insert
            """;

    private static Ast.Trait trait() {
        ParseResult parsed = Parser.parse(SAMPLE);
        assertFalse(parsed.hasErrors(), () -> "语法错误: " + parsed.errors());
        return parsed.trait();
    }

    @Test
    @DisplayName("解析出两个算子与 generated by 子句")
    void structure() {
        Ast.Trait t = trait();
        Ast.Introduces intro = t.sections().stream()
                .filter(Ast.Introduces.class::isInstance)
                .map(Ast.Introduces.class::cast)
                .findFirst()
                .orElseThrow();
        assertEquals(2, intro.signatures().size());
        assertEquals("empty", intro.signatures().get(0).name());
        assertEquals("insert", intro.signatures().get(1).name());

        Ast.Asserts asserts = t.sections().stream()
                .filter(Ast.Asserts.class::isInstance)
                .map(Ast.Asserts.class::cast)
                .findFirst()
                .orElseThrow();
        assertEquals(2, asserts.generatedBy().size());
        assertTrue(asserts.equations().isEmpty());
    }

    @Test
    @DisplayName("generated by 覆盖了两个算子，结构检查无警告")
    void noStructuralFindings() {
        assertTrue(StructureCheck.check(trait()).isEmpty(),
                () -> String.valueOf(StructureCheck.check(trait())));
    }

    @Test
    @DisplayName("没有等式时判决为自洽")
    void verdictConsistent() {
        EquationChecker.SpecReport report = EquationChecker.checkSpec(trait());
        assertEquals(EquationChecker.SpecReport.Verdict.CONSISTENT, report.verdict());
        assertTrue(report.asserts().isEmpty());
        assertTrue(report.implies().isEmpty());
    }

    @Test
    @DisplayName("报告包含 introduces 与结构检查结果")
    void reportContent() {
        String text = EquationChecker.checkSpec(trait()).render();
        assertTrue(text.contains("introduces: empty/0, insert/2"), text);
        assertTrue(text.contains("声明与定义一致"), text);
    }
}
